#!/usr/bin/env node
// Saves the challenges on your live ClassBot (created by you, generated by the
// AI, imported from HackerRank) into a migration file in migrations/.
// Anyone who clones the repo gets them automatically: `npm run setup` and
// `npm run update` apply every migration.
//
//   npm run export:challenges
//
// Safe to run again later: only challenges not exported yet are written, and
// each insert is skipped on a database that already has that challenge.
// Exported challenges become shared (not tied to your Discord server) and the
// author's Discord ID is left out.
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { readFileSync, readdirSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const MIG = join(ROOT, "migrations");
const MAX_FILE = 90_000;      // D1 is happiest with migration files under 100 KB
const MAX_STMT = 95_000;      // and every statement must stay under 100 KB

const COLS = ["source", "kind", "difficulty", "lang", "code_lang", "title", "question", "code", "choices", "answer", "alternatives",
  "hint", "explanation", "topic", "hr_slug", "url", "status", "created_at", "test_set", "time_limit", "solution", "signature"];

// ------------------------------------------------------------ database access
// Normally the live D1 database through wrangler. For testing, point
// CLASSBOT_EXPORT_SQLITE at a local SQLite file instead.
let local = null;
async function query(sql) {
  if (process.env.CLASSBOT_EXPORT_SQLITE) {
    if (!local) {
      const { DatabaseSync } = await import("node:sqlite");
      local = new DatabaseSync(process.env.CLASSBOT_EXPORT_SQLITE);
    }
    return local.prepare(sql).all();
  }
  if (sql.includes('"')) throw new Error("internal: keep double quotes out of SQL");
  const out = await new Promise((resolve, reject) => {
    const child = spawn(`npx --yes wrangler d1 execute classbot-db --remote --json -c wrangler.bot.jsonc --command "${sql.replace(/\s+/g, " ")}"`,
      { cwd: ROOT, shell: true, stdio: ["ignore", "pipe", "pipe"] });
    let o = "", e = "";
    child.stdout.on("data", (d) => (o += d));
    child.stderr.on("data", (d) => (e += d));
    child.on("close", (code) => (code ? reject(new Error((e || o).trim().slice(-1500))) : resolve(o)));
  });
  const start = out.indexOf("[");
  if (start < 0) throw new Error("unexpected answer from wrangler:\n" + out.slice(0, 800));
  const data = JSON.parse(out.slice(start));
  return data.flatMap((r) => r.results ?? []);
}

// ------------------------------------------------------------------ helpers
const sqlStr = (v) => (v === null || v === undefined ? "NULL" : typeof v === "number" ? String(v) : `'${String(v).replace(/'/g, "''")}'`);
const keyOf = (c) => createHash("sha1").update([c.kind, c.difficulty, c.lang, c.title, c.question ?? "", c.code ?? "", c.hr_slug ?? ""].join("\u0001")).digest("hex").slice(0, 16);

function alreadyExported() {
  const keys = new Set();
  for (const f of readdirSync(MIG)) for (const m of readFileSync(join(MIG, f), "utf8").matchAll(/-- export-key: ([0-9a-f]{16})/g)) keys.add(m[1]);
  return keys;
}

/** Keys of every challenge the repo's migrations already create (the built-in bank, earlier exports). */
async function shippedKeys() {
  const keys = new Set();
  try {
    const { DatabaseSync } = await import("node:sqlite");
    const db = new DatabaseSync(":memory:");
    for (const f of readdirSync(MIG).sort()) db.exec(readFileSync(join(MIG, f), "utf8"));
    for (const c of db.prepare("SELECT * FROM challenges").all()) keys.add(keyOf(c));
  } catch (e) {
    console.log(`(couldn't load the built-in bank to compare: ${String(e.message).slice(0, 120)}; exporting everything)`);
  }
  return keys;
}

function nextNumber() {
  const nums = readdirSync(MIG).map((f) => Number(f.slice(0, 4))).filter(Number.isFinite);
  return Math.max(0, ...nums) + 1;
}

function challengeSql(c, key) {
  const set = c.test_set ? `x-${key}` : null;
  const vals = COLS.map((k) => (k === "test_set" ? sqlStr(set) : k === "status" ? sqlStr("active") : sqlStr(c[k])));
  const lines = [`-- export-key: ${key} · ${String(c.title).replace(/[\r\n]+/g, " ").slice(0, 70)}`];
  // skipped if a challenge with the same type, language, title and question exists already
  lines.push(`INSERT INTO challenges (guild_id, ${COLS.join(", ")})
SELECT NULL, ${vals.join(", ")}
WHERE NOT EXISTS (SELECT 1 FROM challenges WHERE kind = ${sqlStr(c.kind)} AND lang = ${sqlStr(c.lang)} AND title = ${sqlStr(c.title)} AND COALESCE(question, '') = ${sqlStr(c.question ?? "")});`);
  for (const tc of c.tests ?? []) {
    lines.push(`INSERT OR IGNORE INTO challenge_tests (test_set, idx, input, gen, expected, sample)
SELECT ${[set, tc.idx, tc.input, tc.gen, tc.expected, tc.sample].map(sqlStr).join(", ")} WHERE EXISTS (SELECT 1 FROM challenges WHERE test_set = ${sqlStr(set)});`);
  }
  return lines;
}

// --------------------------------------------------------------------- main
async function main() {
  console.log("Reading your challenges from Cloudflare D1…");
  const cols = (await query("SELECT name FROM pragma_table_info('challenges')")).map((r) => r.name);
  const have = COLS.filter((c) => cols.includes(c));
  const rows = await query(`SELECT ${have.join(", ")} FROM challenges WHERE source != 'seed' AND status != 'archived' ORDER BY id`);
  const done = alreadyExported();
  for (const k of await shippedKeys()) done.add(k);
  const fresh = [];
  const seen = new Set();
  for (const c of rows) {
    const key = keyOf(c);
    if (done.has(key) || seen.has(key)) continue;
    seen.add(key);
    fresh.push({ ...c, key });
  }
  console.log(`${rows.length} challenge(s) besides the starter bank's seeds; ${fresh.length} not in the repo yet.`);
  if (!fresh.length) return console.log("Nothing new to save.");

  // their tests (write-code problems)
  const sets = [...new Set(fresh.map((c) => c.test_set).filter(Boolean))];
  const tests = new Map();
  for (let i = 0; i < sets.length; i += 20) {
    const part = sets.slice(i, i + 20);
    for (const t of await query(`SELECT test_set, idx, input, gen, expected, sample FROM challenge_tests WHERE test_set IN (${part.map(sqlStr).join(", ")}) ORDER BY test_set, idx`)) {
      if (!tests.has(t.test_set)) tests.set(t.test_set, []);
      tests.get(t.test_set).push(t);
    }
  }

  // write migration files (split to stay under D1's size limits)
  const header = (n) => `-- Challenges exported from a live ClassBot on ${new Date().toISOString().slice(0, 10)} (part ${n}).\n-- Generated by \`npm run export:challenges\`. Safe to apply on any ClassBot database.\n`;
  let num = nextNumber(), part = 1, body = [], size = 0, skipped = 0, written = 0;
  const files = [];
  const flush = () => {
    if (!body.length) return;
    const name = `${String(num).padStart(4, "0")}_my_challenges${part > 1 || files.length ? `_${part}` : ""}.sql`;
    writeFileSync(join(MIG, name), header(part) + "\n" + body.join("\n\n") + "\n");
    files.push(name);
    num++; part++; body = []; size = 0;
  };
  for (const c of fresh) {
    const lines = challengeSql({ ...c, tests: c.test_set ? tests.get(c.test_set) ?? [] : [] }, c.key);
    if (lines.some((l) => l.length > MAX_STMT)) { skipped++; console.log(`  skipped (too big for D1): ${c.title}`); continue; }
    const block = lines.join("\n");
    if (size + block.length > MAX_FILE) flush();
    body.push(block);
    size += block.length;
    written++;
  }
  flush();

  // let the dashboard's diagnostics know about the new files
  const schema = join(ROOT, "src", "shared", "schema.ts");
  if (existsSync(schema) && files.length) {
    const s = readFileSync(schema, "utf8");
    writeFileSync(schema, s.replace(/\];\s*$/m, (m) => `, ${files.map((f) => JSON.stringify(f)).join(", ")}${m}`));
  }
  console.log(`\nSaved ${written} challenge(s) in: ${files.join(", ")}${skipped ? ` (${skipped} too big, skipped)` : ""}`);
  console.log("Commit these files: anyone who installs ClassBot from your repo gets them. Your own database already has them.");
}

main().catch((e) => { console.error("\nExport failed: " + e.message); console.error("Check that you're logged in (npx wrangler whoami) and run it from the classbot folder."); process.exit(1); });
